 "who.teryel": {
  "en": "Teryel",
  "tq": "Teryel",
  "fr": "Teryel",
  "ar": "تريال",
  "who": "",
  "mood": ""
 },
 "t4.intro.1": {
  "en": "On the morning of Yennayer the women baked the bread of the new year in the village oven. By evening the bread was gone, and so was Teryel.",
  "tq": "Ṣbeḥ n Yennayer, tilawin ssewwent aɣrum n useggas amaynut deg ufurnu n taddart. Tameddit, aɣrum ulac-it, Teryel daɣen ulac-itt.",
  "fr": "Le matin de Yennayer, les femmes ont cuit le pain de la nouvelle année au four du village. Le soir, le pain avait disparu, et Teryel aussi.",
  "ar": "صباح يناير، خبزت النساء خبز العام الجديد في فرن القرية. وفي المساء اختفى الخبز، واختفت تريال أيضا.",
  "who": "jida",
  "mood": "telling"
 },
 "t4.intro.2": {
  "en": "Teryel eats bread?",
  "tq": "Teryel tettett aɣrum?",
  "fr": "Teryel mange du pain ?",
  "ar": "تريال تأكل الخبز؟",
  "who": "boy",
  "mood": ""
 },
 "t4.intro.3": {
  "en": "She eats everything. But this bread she hid on the highest roof of the citadel, where her ravens keep watch.",
  "tq": "Tettett kullec. Maca aɣrum-agi teffer-it ɣef ssqef ufellay n Lqelɛa, anda ttɛassan ijeɣdan-is.",
  "fr": "Elle mange de tout. Mais ce pain, elle l'a caché sur le plus haut toit de la citadelle, là où ses corbeaux montent la garde.",
  "ar": "تأكل كل شيء. لكن هذا الخبز خبّأته على أعلى سطح في القلعة، حيث تحرسه غربانها.",
  "who": "jida",
  "mood": "teasing"
 },
 "t4.intro.4": {
  "en": "So Mqidec went up over the roofs, where the tiles are old and loose, and the street is very far below.",
  "tq": "Mqidec yuli ɣef ssqef, anda iqermuden qqduren, ttḥerriken, abrid ddaw-s yebɛed aṭas.",
  "fr": "Alors Mqidec monta sur les toits, là où les tuiles sont vieilles et branlantes, et la rue très loin en dessous.",
  "ar": "فصعد مقيدش فوق السطوح، حيث القرميد قديم ومتخلخل، والشارع بعيد جدا في الأسفل.",
  "who": "jida",
  "mood": "hushed"
 },
 "t4.intro.5": {
  "en": "I don't like ravens.",
  "tq": "Ur ḥemmleɣ ara ijeɣdan.",
  "fr": "Je n'aime pas les corbeaux.",
  "ar": "لا أحب الغربان.",
  "who": "girl",
  "mood": ""
 },
 "t4.s1": {
  "en": "Old tiles slide. Land on a roof and you go down it, faster and faster, and off the edge.",
  "tq": "Iqermuden iqdimen ttḥuddun. Ɣli ɣef ssqef ad tḥuddeḍ fell-as, s zzerb, armi d rrif.",
  "fr": "Les vieilles tuiles glissent. Pose-toi sur un toit et tu le descends, de plus en plus vite, jusqu'au bord.",
  "ar": "القرميد القديم ينزلق. اهبط على سطح فتنزلق عليه، أسرع فأسرع، حتى الحافة.",
  "who": "jida",
  "mood": ""
 },
 "t4.s1.child": {
  "en": "Like the snow on the hill!",
  "tq": "Am udfel deg wedrar!",
  "fr": "Comme la neige sur la colline !",
  "ar": "مثل الثلج على التلّ!",
  "who": "boy",
  "mood": ""
 },
 "t4.s2": {
  "en": "The ravens sleep under the stacks of loose tiles. Hit a stack hard and it goes over the edge.",
  "tq": "Ijeɣdan ṭṭsen ddaw ikedduse n iqermuden. Wwet akeddus s ǧǧehd ad yeɣli seg rrif.",
  "fr": "Les corbeaux dorment sous les piles de tuiles branlantes. Frappe une pile fort, et elle bascule par-dessus le bord.",
  "ar": "تنام الغربان تحت أكوام القرميد المتخلخل. اضرب كومة بقوّة فتسقط من الحافة.",
  "who": "jida",
  "mood": ""
 },
 "t4.s2.child": {
  "en": "On the ravens?",
  "tq": "Ɣef ijeɣdan?",
  "fr": "Sur les corbeaux ?",
  "ar": "على الغربان؟",
  "who": "girl",
  "mood": ""
 },
 "t4.s3": {
  "en": "Slide down a roof fast enough, and you hit the stack at the bottom without even trying.",
  "tq": "Ḥudd ɣef ssqef s zzerb, ad tewteḍ akeddus ddaw-s war ma tɛerḍeḍ.",
  "fr": "Glisse assez vite le long d'un toit, et tu frappes la pile en bas sans même essayer.",
  "ar": "انزلق على السطح بسرعة كافية، فتضرب الكومة في الأسفل دون أن تحاول.",
  "who": "jida",
  "mood": ""
 },
 "t4.s3.child": {
  "en": "Faster!",
  "tq": "S zzerb!",
  "fr": "Plus vite !",
  "ar": "أسرع!",
  "who": "boy",
  "mood": ""
 },
 "t4.s4": {
  "en": "And there she was, on the flat roof, sitting by the chimney with the bread in her lap.",
  "tq": "Atan dinna, ɣef ssqef yettwaɛdlen, teqqim ɣer ddexxan, aɣrum ɣef tgecrar-is.",
  "fr": "Et elle était là, sur le toit plat, assise près de la cheminée, le pain sur les genoux.",
  "ar": "وكانت هناك، على السطح المستوي، جالسة قرب المدخنة والخبز في حجرها.",
  "who": "jida",
  "mood": "hushed"
 },
 "t4.s4.child": {
  "en": "The stack! Above her!",
  "tq": "Akeddus! Nnig-s!",
  "fr": "La pile ! Au-dessus d'elle !",
  "ar": "الكومة! فوقها!",
  "who": "girl",
  "mood": ""
 },
 "t4.end.1": {
  "en": "He slid down the roof into the last stack of tiles. It came down on her, and she went down the chimney like a sack of flour.",
  "tq": "Yeḥudd ɣef ssqef ɣer ukeddus aneggaru. Yeɣli fell-as, teɣli deg ddexxan am tcekkart n uwren.",
  "fr": "Il glissa le long du toit jusque dans la dernière pile de tuiles. Elle lui tomba dessus, et elle descendit par la cheminée comme un sac de farine.",
  "ar": "انزلق على السطح نحو آخر كومة قرميد. فسقطت عليها، فنزلت عبر المدخنة ككيس طحين.",
  "who": "jida",
  "mood": "telling"
 },
 "t4.end.2": {
  "en": "My bread! Who took my bread?!",
  "tq": "Aɣrum-iw! Anwa i yeddmen aɣrum-iw?!",
  "fr": "Mon pain ! Qui a pris mon pain ?!",
  "ar": "خبزي! من أخذ خبزي؟!",
  "who": "teryel",
  "mood": ""
 },
 "t4.end.3": {
  "en": "It was never her bread. He carried it home across the roofs, still warm.",
  "tq": "Ur yelli ara d aɣrum-is. Yerra-t s axxam ɣef ssqef, mazal yeḥma.",
  "fr": "Ce n'était pas son pain. Il le rapporta à la maison par les toits, encore chaud.",
  "ar": "لم يكن خبزها أبدا. حمله إلى البيت عبر السطوح، وما زال دافئا.",
  "who": "jida",
  "mood": "teasing"
 },
 "t4.end.4": {
  "en": "Can we eat it now?",
  "tq": "Nezmer ad t-nečč tura?",
  "fr": "On peut le manger maintenant ?",
  "ar": "هل نستطيع أكله الآن؟",
  "who": "boy",
  "mood": ""
 },
 "t4.end.5": {
  "en": "After the tale. Always after the tale.",
  "tq": "Deffir tmacahut. Yal tikkelt deffir tmacahut.",
  "fr": "Après le conte. Toujours après le conte.",
  "ar": "بعد الحكاية. دائما بعد الحكاية.",
  "who": "jida",
  "mood": "teasing"
 },
 "tip.slide": {
  "en": "Old tiles slide. Land on a roof to slide down it, fast. Tap to hop off.",
  "tq": "Iqermuden iqdimen ttḥuddun. Ɣli ɣef ssqef ad tḥuddeḍ. Sṭebṭeb ad tneggzeḍ.",
  "fr": "Les vieilles tuiles glissent. Pose-toi sur un toit pour le descendre vite. Tape pour sauter.",
  "ar": "القرميد القديم ينزلق. اهبط على سطح لتنزلق عليه بسرعة. انقر لتقفز.",
  "who": "",
  "mood": ""
 },
 "tip.knock": {
  "en": "Loose tiles. Hit the stack hard and it goes over the edge, onto whatever is below.",
  "tq": "Iqermuden ttḥerriken. Wwet akeddus s ǧǧehd ad yeɣli seg rrif ɣef wayen yellan ddaw-s.",
  "fr": "Des tuiles branlantes. Frappe la pile fort et elle bascule, sur ce qui se trouve en dessous.",
  "ar": "قرميد متخلخل. اضرب الكومة بقوّة فتسقط من الحافة على ما تحتها.",
  "who": "",
  "mood": ""
 },
 "tip.raven": {
  "en": "Her ravens. Hit them fast, or they peck.",
  "tq": "Ijeɣdan-is. Wwet-iten s zzerb, neɣ ad k-qqsen.",
  "fr": "Ses corbeaux. Frappe-les vite, ou ils piquent.",
  "ar": "غربانها. اضربها بسرعة، وإلا نقرتك.",
  "who": "",
  "mood": ""
 },
 "r.slide": {
  "en": "Wheee!",
  "tq": "Iwwah!",
  "fr": "Youpi !",
  "ar": "ووو!",
  "who": "boy",
  "mood": ""
 },
 "r.knock": {
  "en": "It fell!",
  "tq": "Yeɣli!",
  "fr": "Elle est tombée !",
  "ar": "سقطت!",
  "who": "girl",
  "mood": ""
 },
